(function () {
  const SPRITES = {
    blink1: 'data:image/png;base64,',
    blink2: 'data:image/png;base64,',
    blink3: 'data:image/png;base64,',
    blink4: 'data:image/png;base64,',
    mouth1: 'data:image/png;base64,',
    mouth2: 'data:image/png;base64,',
    mouth3: 'data:image/png;base64,',
    mouth4: 'data:image/png;base64,',
    earR: 'data:image/png;base64,',
    earL: 'data:image/png;base64,',
    angry: 'data:image/png;base64,',
    smile: 'data:image/png;base64,'
  };

  // Preload all 12 sprites for flicker-free animation
  Object.values(SPRITES).forEach((src) => {
    const img = new Image();
    img.src = src;
  });

  // Simple Web Audio retro blip for Space Cat speech
  let audioCtx = null;
  function playCatBlip(pitch) {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      if (!audioCtx) audioCtx = new AC();
      if (audioCtx.state === 'suspended') return;
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(pitch || 620, audioCtx.currentTime);
      gain.gain.setValueAtTime(0.03, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.045);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.05);
    } catch (e) {}
  }

  class SpaceCatAnimator {
    constructor(imgEl, textEl, options) {
      this.imgEl = imgEl;
      this.textEl = textEl;
      this.opts = Object.assign({ sound: false }, options || {});
      this.mood = 'normal'; // normal | angry | smile
      this.isSpeaking = false;
      this.isBlinking = false;
      this.speechTimer = null;
      this.idleTimer = null;
      this.moodLockTimer = null;
      this.setSprite(SPRITES.mouth1);
      this.startIdleLoop();
    }

    setSprite(src) {
      if (this.imgEl && this.imgEl.getAttribute('src') !== src) {
        this.imgEl.setAttribute('src', src);
      }
    }

    startIdleLoop() {
      const tick = () => {
        if (!this.isSpeaking && !this.isBlinking) {
          if (this.mood === 'angry') {
            this.setSprite(SPRITES.angry);
          } else if (this.mood === 'smile') {
            this.setSprite(SPRITES.smile);
          } else {
            const roll = Math.random();
            if (roll < 0.65) {
              this.playBlink();
            } else if (roll < 0.82) {
              this.playEarTwitch('R');
            } else {
              this.playEarTwitch('L');
            }
          }
        }
        this.idleTimer = setTimeout(tick, 2200 + Math.random() * 2000);
      };
      this.idleTimer = setTimeout(tick, 1800);
    }

    playBlink() {
      if (this.isSpeaking || this.mood !== 'normal') return;
      this.isBlinking = true;
      const seq = [SPRITES.blink1, SPRITES.blink2, SPRITES.blink3, SPRITES.blink4, SPRITES.blink2, SPRITES.mouth1];
      seq.forEach((src, i) => {
        setTimeout(() => {
          if (!this.isSpeaking && this.mood === 'normal') this.setSprite(src);
          if (i === seq.length - 1) this.isBlinking = false;
        }, i * 55);
      });
    }

    playEarTwitch(side) {
      if (this.isSpeaking || this.mood !== 'normal') return;
      this.isBlinking = true;
      const ear = side === 'L' ? SPRITES.earL : SPRITES.earR;
      this.setSprite(ear);
      setTimeout(() => {
        if (!this.isSpeaking && this.mood === 'normal') this.setSprite(SPRITES.mouth1);
        this.isBlinking = false;
      }, 240);
    }

    say(text, mood, durationMs) {
      if (this.speechTimer) clearInterval(this.speechTimer);
      if (this.moodLockTimer) clearTimeout(this.moodLockTimer);

      this.mood = mood || 'normal';
      this.isSpeaking = true;
      if (this.textEl) this.textEl.textContent = '';

      const mouthFrames = [SPRITES.mouth2, SPRITES.mouth3, SPRITES.mouth4, SPRITES.mouth2, SPRITES.mouth1];
      let idx = 0;
      let frameIdx = 0;

      this.speechTimer = setInterval(() => {
        if (idx < text.length) {
          if (this.textEl) this.textEl.textContent += text.charAt(idx);
          if (idx % 2 === 0) {
            if (this.mood === 'angry' && idx % 6 === 0) {
              this.setSprite(SPRITES.angry);
            } else if (this.mood === 'smile' && idx % 6 === 0) {
              this.setSprite(SPRITES.smile);
            } else {
              this.setSprite(mouthFrames[frameIdx % mouthFrames.length]);
              frameIdx++;
            }
            if (this.opts.sound) playCatBlip(this.mood === 'angry' ? 420 : 680 + Math.random() * 140);
          }
          idx++;
        } else {
          clearInterval(this.speechTimer);
          this.speechTimer = null;
          this.isSpeaking = false;
          if (this.mood === 'angry') this.setSprite(SPRITES.angry);
          else if (this.mood === 'smile') this.setSprite(SPRITES.smile);
          else this.setSprite(SPRITES.mouth1);

          if (durationMs && durationMs > 0) {
            this.moodLockTimer = setTimeout(() => {
              this.mood = 'normal';
              this.setSprite(SPRITES.mouth1);
            }, durationMs);
          }
        }
      }, 28);
    }
  }

  function createFloatingWidget(initialLine, tapLines) {
    const style = document.createElement('style');
    style.textContent = `
      #sc-widget {
        position: fixed;
        bottom: 14px;
        left: 14px;
        z-index: 95;
        display: flex;
        align-items: flex-end;
        gap: 10px;
        max-width: min(360px, calc(100vw - 28px));
        font-family: 'Hiragino Kaku Gothic ProN', 'Yu Gothic', sans-serif;
        pointer-events: none;
      }
      #sc-avatar-btn {
        pointer-events: auto;
        width: 76px;
        height: 76px;
        flex-shrink: 0;
        border-radius: 16px;
        background: rgba(12, 16, 28, 0.92);
        border: 2px solid #38bdf8;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.6);
        padding: 4px;
        cursor: pointer;
        transition: transform 0.15s ease;
      }
      #sc-avatar-btn:active { transform: scale(0.93); }
      #sc-avatar-img { width: 100%; height: 100%; object-fit: contain; display: block; }
      #sc-bubble {
        pointer-events: auto;
        background: rgba(12, 16, 28, 0.94);
        border: 1.5px solid #38bdf8;
        border-radius: 14px;
        padding: 9px 12px;
        color: #f1f5f9;
        font-size: 12px;
        line-height: 1.45;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.6);
        position: relative;
      }
      #sc-bubble.is-hidden { display: none; }
      #sc-close {
        position: absolute;
        top: 4px;
        right: 7px;
        background: none;
        border: none;
        color: #94a3b8;
        font-size: 11px;
        cursor: pointer;
        padding: 0 2px;
      }
      #sc-name { font-size: 10px; font-weight: bold; color: #38bdf8; margin-bottom: 2px; }
      #sc-text { padding-right: 12px; }
    `;
    document.head.appendChild(style);

    const wrap = document.createElement('div');
    wrap.id = 'sc-widget';
    wrap.innerHTML = `
      <button id="sc-avatar-btn" type="button" title="スペース猫をタップ！">
        <img id="sc-avatar-img" src="data:image/png;base64," alt="スペース猫">
      </button>
      <div id="sc-bubble">
        <button id="sc-close" type="button" title="吹き出しを隠す">✕</button>
        <div id="sc-name">スペース猫（実況中）</div>
        <div id="sc-text"></div>
      </div>
    `;
    document.body.appendChild(wrap);

    const imgEl = document.getElementById('sc-avatar-img');
    const textEl = document.getElementById('sc-text');
    const bubbleEl = document.getElementById('sc-bubble');
    const closeBtn = document.getElementById('sc-close');
    const avatarBtn = document.getElementById('sc-avatar-btn');

    const anim = new SpaceCatAnimator(imgEl, textEl, { sound: false });
    if (initialLine) anim.say(initialLine, 'normal', 4000);

    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      bubbleEl.classList.add('is-hidden');
    });

    const lines = tapLines && tapLines.length ? tapLines : [
      { text: 'クリアするまで帰さないにゃ！', mood: 'angry' },
      { text: 'このゲーム、なかなか手強いだろにゃ？', mood: 'normal' },
      { text: '3つ全部クリアしたらご褒美だにゃ！', mood: 'smile' }
    ];
    let tapIdx = 0;

    avatarBtn.addEventListener('click', () => {
      bubbleEl.classList.remove('is-hidden');
      const item = lines[tapIdx % lines.length];
      tapIdx++;
      anim.say(item.text, item.mood, 3500);
    });

    return {
      say(text, mood, durationMs) {
        bubbleEl.classList.remove('is-hidden');
        anim.say(text, mood, durationMs || 4500);
      }
    };
  }

  window.SpaceCat = {
    SPRITES,
    SpaceCatAnimator,
    createFloatingWidget
  };
})();
